export type CultivationEventKind = 'normal' | 'good' | 'danger' | 'realm';
export interface CultivationEvent {
  id: number;
  event: string;
  kind: CultivationEventKind;
  weight?: number;
  minRealm?: number;
  maxRealm?: number;
  minLuck?: number;
  minAge?: number;
  maxAge?: number;
  once?: boolean;
  fatal?: boolean;
  effect?: Partial<Allocation>;
  trainingFactor?: number;
  category?: string;
  scene?: number;
}

