for (const [scene, realm, category, opening, results] of scenes) {
  results.forEach(([outcome, ending], index) => {
    const id = scene + index;
    const { suffix, ...result } = outcomes[outcome];
    if (cultivationEvents.has(id)) throw new Error(`Duplicate cultivation event: ${id}`);
    cultivationEvents.set(id, {
      id, scene, category, minRealm: realm, maxRealm: realm, weight: 4, once: true,
      ...result, event: `${opening}${ending}${suffix}`,
    });
  });
}

export function formatCultivationEvent(id: number, values: Record<string, string | number> = {}) {
  const event = cultivationEvents.get(id);
  if (!event) throw new Error(`Unknown cultivation event: ${id}`);
  return event.event.replace(/\{(\w+)\}/g, (_, key) => {
    if (values[key] === undefined) throw new Error(`Missing cultivation event parameter: ${key}`);
    return String(values[key]);
  });
}

export function cultivationEventPool(realm: number, luck: number, seen: ReadonlySet<number>, age = 0) {
  return Array.from(cultivationEvents.values())
    .filter(event => event.weight && realm >= (event.minRealm || 0) && realm <= (event.maxRealm ?? 13) &&
      luck >= (event.minLuck || 0) && age >= (event.minAge || 0) && age <= (event.maxAge ?? Infinity) &&
      !(event.once && seen.has(event.id)))
    .map(event => [event.id, event.weight!] as [number, number]);
}
